const C={paper:'#fdfcf8',ink:'#2d3142',muted:'#4f5d75',rule:'#c5c6c2',accent:'#bf4520'};
const text=(x,y,t,size=32,color=C.ink,anchor='middle',mono=false)=>`<text x="${x}" y="${y}" font-family="${mono?"'Playfair Display',Georgia,serif":"'Playfair Display',Georgia,serif"}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${t}</text>`;
function panel(series,x,w,xmax,ymax,color){
 const top=128,bottom=388,h=bottom-top,px=a=>x+a/xmax*w,py=t=>bottom-t/ymax*h,points=series.data.filter(r=>Number.isFinite(r.angle_deg)&&Number.isFinite(r.torque_Nm));let s='';
 s+=text(x+w/2,44,`P = 2 · a = 0.7 · b = ${series.geometry.axial_depth_mm} mm`,34,C.ink);
 s+=text(x,92,'Torque (N·m)',32,C.muted,'start');
 for(let i=0;i<=4;i++){const v=ymax*i/4,y=py(v);s+=`<line x1="${x}" y1="${y}" x2="${x+w}" y2="${y}" stroke="${C.rule}" stroke-width="1"/>`+text(x-20,y+10,Number(v.toFixed(2)),32,C.muted,'end',true);}
 for(let i=0;i<=4;i++){const a=xmax*i/4,xx=px(a);s+=`<line x1="${xx}" y1="${bottom}" x2="${xx}" y2="${bottom+8}" stroke="${C.muted}" stroke-width="1.2"/>`+text(xx,bottom+44,Number(a.toFixed(2)),32,C.muted,'middle',true);}
 s+=`<path d="M${x} ${top}V${bottom}H${x+w}" fill="none" stroke="${C.muted}" stroke-width="1.6"/><polyline points="${points.map(r=>[px(r.angle_deg),py(r.torque_Nm)].join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="3.2" stroke-linejoin="round"/>`;
 for(const r of points)s+=`<circle cx="${px(r.angle_deg)}" cy="${py(r.torque_Nm)}" r="4.5" fill="${color}"/>`;
 return s+text(x+w/2,478,'Rotation (°)',32,C.muted);
}
export function buildArchivedSpringChart(){
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 540" width="1600" height="540" role="img" aria-labelledby="archived-prototype-title archived-prototype-desc"><title id="archived-prototype-title">Archived ANSYS prototype spring curves</title><desc id="archived-prototype-desc">Original positive-loading torque tables for P2mm a0.7mm prototypes with axial depths10 and20mm, shown on separately labelled axes without smoothing or extrapolation.</desc>${panel(ARCHIVED_SPRING_CURVES.series[0],112,600,120,20,C.accent)}${panel(ARCHIVED_SPRING_CURVES.series[1],952,528,45,1.2,C.muted)}${text(800,530,'Archived prototypes · separate scales · not a calibrated current-pair law',32,C.muted)}</svg>`;
}
